const state={folder:'inbox',category:'focused',label:'',selected:null,selectedIds:new Set(),messages:[],attachments:[],encrypted:true,lastSent:null,undoTimer:null,triage:[],tasks:[],staff:{name:'Oak Haven Staff',email:'staff@oakhavensuites.com',role:'Staff'}};
const $=s=>document.querySelector(s);
const seed=[
{id:1,folder:'inbox',from:'Guest Services',email:'reservations@oakhavensuites.com',subject:'Re: Reservation Inquiry',preview:'Thank you for your interest in Oak Haven...',time:'10:24 AM',unread:true,star:true,body:`Dear Guest,<br><br>Thank you for your interest in Oak Haven Lodging & Suites.<br><br>We are delighted to assist you with your reservation inquiry. Please let us know your preferred dates, room type, and any special requests, and our team will be happy to confirm availability.<br><br>We look forward to welcoming you to Oak Haven — Where Comfort Feels Like Home!<br><br>Warm regards,<br><b>Guest Services Team</b><br>Oak Haven Lodging & Suites`},
{id:3,folder:'inbox',from:'Management Team',email:'management@oakhavensuites.com',subject:'Weekly Operations Update',preview:'Please review the attached operations report...',time:'8:42 AM',unread:false,star:false,body:`Team,<br><br>Please review this week's operations update. Priority items include reservations, housekeeping turnaround, maintenance tracking, and guest service follow-up.<br><br>Regards,<br>Management`},
{id:5,folder:'inbox',from:'Housekeeping',email:'housekeeping@oakhavensuites.com',subject:'Room Readiness Update',preview:'All assigned rooms for today are ready...',time:'Yesterday',unread:false,star:true,body:`Front Desk,<br><br>All assigned rooms for today's arrivals have completed housekeeping inspection and are marked ready for guest check-in.<br><br>Housekeeping Team`}
];

async function loadMessages(){
  try{const r=await fetch('/api/messages'); if(r.ok) state.messages=await r.json(); else throw 0}catch{state.messages=seed}
  state.messages=state.messages.map((m,i)=>({...m,category:m.category||(['updates','social','promotions','forums'][i%4]),label:m.label||(m.email?.endsWith('@oakhavensuites.com')?'operations':'guest'),threadId:m.threadId||String(m.subject||'').replace(/^(re|fwd):\s*/i,'').toLowerCase()}));
  renderList();
}
function matchesSearch(m,q){if(!q)return true;const fields=[m.from,m.email,m.to,m.subject,m.preview,m.body,m.attachments?.map(x=>x.name).join(' ')].join(' ').toLowerCase();const ops={from:m.email,to:m.to,subject:m.subject,label:m.label};return q.split(/\s+/).every(token=>{const pair=token.split(':');if(pair.length>1&&ops[pair[0]])return String(ops[pair[0]]).toLowerCase().includes(pair.slice(1).join(':'));if(token==='has:attachment')return Boolean(m.attachments?.length);return fields.includes(token)})}
function isFocused(m){return m.unread||m.star||['urgent','finance','operations'].includes(m.label)||String(m.email||'').endsWith('@oakhavensuites.com')}
function filtered(){const q=$('#searchInput').value.trim().toLowerCase(),now=Date.now();return state.messages.filter(m=>(state.folder==='starred'?m.star:m.folder===state.folder)&&(state.category==='focused'?isFocused(m):state.category==='other'?!isFocused(m):(!state.category||state.category==='all'||m.category===state.category))&&(!state.label||m.label===state.label)&&(!m.snoozedUntil||m.snoozedUntil<=now)&&matchesSearch(m,q))}
function renderList(){const list=$('#mailList'); list.innerHTML='';const items=filtered();$('#folderTitle').textContent=state.folder[0].toUpperCase()+state.folder.slice(1);$('#inboxCount').textContent=state.messages.filter(m=>m.folder==='inbox'&&m.unread).length;if(!items.length){list.innerHTML='<div style="padding:28px;color:#6b7572;text-align:center">No messages found.</div>';return}items.forEach(m=>{const el=document.createElement('div');el.className='mail-item'+(m.unread?' unread':'')+(state.selected===m.id?' active':'');el.innerHTML=`<input class="mail-check" type="checkbox" aria-label="Select ${esc(m.subject)}" data-mail-check="${m.id}" ${state.selectedIds.has(m.id)?'checked':''}><div class="mail-icon">${initials(m.from)}</div><div class="mail-copy"><div class="row"><div class="sender">${esc(m.from)}</div><div class="mail-time">${esc(m.time||'')}</div></div><div class="subject">${esc(m.subject)}</div><div class="preview">${esc(m.preview||'')}</div></div><div class="star">${m.star?'★':'☆'}</div>`;el.onclick=e=>{if(e.target.matches('[data-mail-check]')){e.target.checked?state.selectedIds.add(m.id):state.selectedIds.delete(m.id);return}openMessage(m.id)};list.appendChild(el)})}
function openMessage(id){const m=state.messages.find(x=>x.id===id);if(!m)return;state.selected=id;m.unread=false;hideAlternateViews();$('#emptyState').classList.add('hidden');$('#readerContent').classList.remove('hidden');$('#recallBtn').classList.toggle('hidden',m.folder!=='sent');$('#messageSubject').textContent=m.subject;$('#messageFrom').textContent=`${m.from} <${m.email}>`;$('#messageMeta').textContent=m.to?`to ${m.to}${m.cc?` · cc ${m.cc}`:''}`:'to me';$('#messageTime').textContent=m.time||'';$('#senderAvatar').textContent=initials(m.from);const thread=state.messages.filter(x=>x.threadId===m.threadId).reverse();$('#messageBody').innerHTML=thread.length>1?thread.map(x=>`<section class="thread-message"><div><b>${esc(x.from)}</b><small>${esc(x.time||'')}</small></div><p>${x.body}</p></section>`).join(''):m.body;const external=!m.email?.endsWith('@oakhavensuites.com');$('#intentLabel').textContent=`${external?'External guest/vendor':'Internal operations'} · ${m.label==='urgent'?'High priority':'Routine'}`;$('#recommendedAction').textContent=m.label==='finance'?'Route to management approval':external?'Draft a grounded guest response':'Create and assign an operational task';renderList();renderNotifications()}
function initials(s){return s.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase()}
function esc(s=''){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function compose(){ $('#composeModal').classList.remove('hidden'); $('#fromField').value=state.staff.email; $('#toField').focus() }
function closeCompose(){ $('#composeModal').classList.add('hidden'); $('#composeForm').reset();$('#fromField').value=state.staff.email;state.attachments=[];renderAttachments();$('#ccFieldWrap').classList.add('hidden');$('#bccFieldWrap').classList.add('hidden');$('#routeBadge').textContent='Enter a recipient';$('#routeBadge').className='route-badge' }
function routeBadge(){const v=$('#toField').value.trim().toLowerCase();const b=$('#routeBadge');if(!v){b.textContent='Enter a recipient';b.className='route-badge';return}const internal=v.endsWith('@oakhavensuites.com');b.textContent=internal?'Internal secure route':'External encrypted route';b.className='route-badge '+(internal?'internal':'external')}
function toast(t){const x=$('#toast');x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),2800)}
async function sendMessage(e){e.preventDefault();const body=$('#bodyField').value.trim();if(/\battach(?:ed|ment)?\b/i.test(body)&&!state.attachments.length&&!confirm('You mentioned an attachment but no file is attached. Send anyway?'))return;const schedule=$('#scheduleField').value,scheduleAt=schedule==='custom'?$('#scheduleDateField').value:schedule;const payload={from:state.staff.email,to:$('#toField').value.trim(),cc:$('#ccField').value.trim(),bcc:$('#bccField').value.trim(),subject:$('#subjectField').value.trim(),body,attachments:[...state.attachments],encrypted:state.encrypted,encryptionMode:$('#encryptionMode').value,schedule:scheduleAt};const message={id:Date.now(),folder:'sent',from:'Me',email:payload.from,to:payload.to,cc:payload.cc,bcc:payload.bcc,attachments:payload.attachments,encrypted:payload.encrypted,encryptionMode:payload.encryptionMode,scheduled:schedule!=='now',sentAt:Date.now(),readByRecipient:false,subject:payload.subject,preview:payload.body.slice(0,70),time:schedule==='now'?'Now':`Scheduled · ${scheduleAt}`,body:esc(payload.body).replace(/\n/g,'<br>'),category:'updates',label:'operations',threadId:String(payload.subject).replace(/^(re|fwd):\s*/i,'').toLowerCase()};state.messages.unshift(message);state.lastSent=message;closeCompose();showUndo();toast(schedule!=='now'?'Message scheduled':payload.to.endsWith('@oakhavensuites.com')?'Message routed securely inside Oak Haven':'Draft queued — connect the Oak Haven mail gateway for external delivery');renderList()}

async function loadStaffIdentity(){try{const r=await fetch('/api/admin/session',{headers:{accept:'application/json'}}),d=await r.json();if(!r.ok||!d.user)return;state.staff.name=d.user.name||state.staff.name;state.staff.email=d.user.email||state.staff.email;state.staff.role=d.user.role||state.staff.role;$('#staffDisplayName').textContent=state.staff.name;$('#staffEmail').textContent=`${state.staff.email} · ${state.staff.role}`;$('#staffAvatar').textContent=initials(state.staff.name);$('#fromField').value=state.staff.email}catch{}}

document.querySelectorAll('.nav-item[data-folder]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.nav-item').forEach(x=>x.classList.remove('active'));b.classList.add('active');state.folder=b.dataset.folder;state.selected=null;hideAlternateViews();$('#emptyState').classList.remove('hidden');renderList()}));
$('#composeBtn').onclick=compose;$('#closeCompose').onclick=closeCompose;$('#composeForm').onsubmit=sendMessage;$('#toField').oninput=routeBadge;$('#searchInput').oninput=renderList;$('#refreshBtn').onclick=()=>{toast('Mailbox refreshed');loadMessages()};$('#replyBtn').onclick=()=>{const m=state.messages.find(x=>x.id===state.selected);if(m){compose();$('#toField').value=m.email;$('#subjectField').value='Re: '+m.subject;routeBadge()}};
$('#composeModal').addEventListener('click',e=>{if(e.target.id==='composeModal')closeCompose()});

function selectedMessage(){return state.messages.find(x=>x.id===state.selected)}
function cleanSubject(prefix,subject){return `${prefix}: ${String(subject||'').replace(/^(re|fwd):\s*/i,'')}`}
function quoteMessage(m){return `\n\n— Original message —\nFrom: ${m.from} <${m.email}>\nSubject: ${m.subject}\n\n${String(m.body||'').replace(/<br\s*\/?>/gi,'\n').replace(/<[^>]+>/g,'')}`}
function prepareReply(mode){const m=selectedMessage();if(!m)return toast('Select a message first');compose();if(mode==='forward'){$('#subjectField').value=cleanSubject('Fwd',m.subject);$('#bodyField').value=quoteMessage(m);return}$('#toField').value=m.email;$('#subjectField').value=cleanSubject('Re',m.subject);if(mode==='all'){const recipients=[m.to,m.cc].filter(Boolean).join(',').split(',').map(x=>x.trim()).filter(x=>x&&x.toLowerCase()!==state.staff.email.toLowerCase()&&x.toLowerCase()!==m.email.toLowerCase());if(recipients.length){$('#ccFieldWrap').classList.remove('hidden');$('#ccField').value=[...new Set(recipients)].join(', ')}}routeBadge()}
function moveSelected(folder){const m=selectedMessage();if(!m)return toast('Select a message first');m.folder=folder;m.unread=false;state.selected=null;$('#readerContent').classList.add('hidden');$('#emptyState').classList.remove('hidden');renderList();renderNotifications();toast(folder==='archive'?'Message archived':'Message moved to Trash')}
function useSmartReply(text){const m=selectedMessage();if(!m)return;prepareReply('reply');$('#bodyField').value=text==='Thank you!'?'Thank you for the update.':text==='Please confirm.'?'Please confirm the details and next steps.':'Looks good! Please proceed.'}
function hideAlternateViews(){$('#teamView').classList.add('hidden');$('#aiView').classList.add('hidden');$('#productivityView').classList.add('hidden');$('#readerPanel').classList.remove('team-mode','ai-mode','productivity-mode')}
function renderAttachments(){$('#attachmentList').innerHTML=state.attachments.map((f,i)=>`<span>📎 ${esc(f.name)} <small>${Math.max(1,Math.round(f.size/1024))} KB</small><button type="button" data-remove-attachment="${i}" aria-label="Remove ${esc(f.name)}">Remove</button></span>`).join('')}
function addAttachments(files){state.attachments.push(...[...files].map(f=>({name:f.name,size:f.size,type:f.type})));renderAttachments()}
function renderNotifications(){const unread=state.messages.filter(m=>m.folder==='inbox'&&m.unread);$('#notificationCount').textContent=unread.length;$('#notificationCount').classList.toggle('hidden',!unread.length);$('#notificationList').innerHTML=unread.length?unread.map(m=>`<button data-notification-id="${m.id}"><b>${esc(m.from)}</b><span>${esc(m.subject)}</span></button>`).join(''):'<p>You are all caught up.</p>'}
function openAiWorkspace(){document.querySelectorAll('.nav-item').forEach(x=>x.classList.remove('active'));$('#havenAiBtn').classList.add('active');document.querySelectorAll('.team-spaces button').forEach(x=>x.classList.remove('active'));state.selected=null;hideAlternateViews();$('#readerContent').classList.add('hidden');$('#emptyState').classList.add('hidden');$('#readerPanel').classList.add('ai-mode');$('#aiView').classList.remove('hidden');$('#folderTitle').textContent='Haven AI'}
const agentRules=[
  {test:/refund|invoice|credit|payment|billing|financial/i,intent:'Finance approval',department:'Accounting',agent:'Finance Agent',route:'accounting@oakhavensuites.com',risk:'Sensitive',action:'Hold for management approval'},
  {test:/overnight|late checkout|exception|policy/i,intent:'Policy exception',department:'Front Desk',agent:'Guest Relations Agent',route:'reception@oakhavensuites.com',risk:'Sensitive',action:'Draft and send to HITL review'},
  {test:/air.?condition|\bac\b|repair|maintenance|plumbing|television|\btv\b|wi-?fi/i,intent:'Maintenance request',department:'IT & Engineering',agent:'Operations Agent',route:'operations@oakhavensuites.com',risk:'Routine',action:'Create and dispatch work order'},
  {test:/towel|clean|housekeeping|linen|room readiness/i,intent:'Room operations',department:'Housekeeping',agent:'Operations Agent',route:'housekeeping@oakhavensuites.com',risk:'Routine',action:'Create mobile staff task'},
  {test:/book|reservation|availability|room|check.?in|arrival/i,intent:'Reservation inquiry',department:'Reservations',agent:'Guest Relations Agent',route:'reservations@oakhavensuites.com',risk:'Routine',action:'Draft grounded guest response'},
  {test:/vendor|service visit|supplier/i,intent:'Vendor coordination',department:'Operations',agent:'Operations Agent',route:'operations@oakhavensuites.com',risk:'Routine',action:'Log and notify operations'},
  {test:/.*/i,intent:'General correspondence',department:'Guest Services',agent:'Guest Relations Agent',route:'reception@oakhavensuites.com',risk:'Routine',action:'Draft for staff review'}
];
function classifyMessage(m){const text=[m.subject,m.preview,String(m.body||'').replace(/<[^>]+>/g,' ')].join(' ');const rule=agentRules.find(r=>r.test.test(text));const external=!String(m.email||'').endsWith('@oakhavensuites.com');return {...rule,messageId:m.id,subject:m.subject,source:external?'External':'Internal',sentiment:/complaint|angry|unacceptable|urgent/i.test(text)?'Needs attention':'Neutral',context:rule.intent==='Reservation inquiry'?'Suite availability · guest CRM · arrival policy':rule.intent==='Room operations'?'Housekeeping schedule · room status · arrival queue':rule.intent==='Policy exception'?'Guest stay · overnight visitor policy · room occupancy':'PMS record · operating procedures'}}
function renderAgentActivity(){const box=$('#agentActivity');if(!box)return;box.innerHTML=state.triage.length?state.triage.map((x,i)=>`<article class="activity-row"><span class="activity-index">${i+1}</span><div><b>${esc(x.subject)}</b><small>${esc(x.source)} · ${esc(x.intent)} · ${esc(x.sentiment)}</small><p><strong>${esc(x.agent)}</strong> → ${esc(x.route)}<br>${esc(x.context)}</p></div><span class="risk ${x.risk.toLowerCase()}">${esc(x.risk)}</span></article>`).join(''):'<p class="activity-empty">Run inbox triage to enrich messages and route the first workflow.</p>';$('#triagedMetric').textContent=state.triage.length;$('#routineMetric').textContent=state.triage.filter(x=>x.risk==='Routine').length;$('#reviewMetric').textContent=state.triage.filter(x=>x.risk==='Sensitive').length+document.querySelectorAll('.review-item:not(.resolved)').length;$('#taskMetric').textContent=state.tasks.length}
function triageInbox(){state.triage=state.messages.filter(m=>m.folder==='inbox').map(classifyMessage);renderAgentActivity();localStorage.setItem('havenroute.triage',JSON.stringify(state.triage));toast(`Haven AI enriched and routed ${state.triage.length} inbox messages`)}
function runNextWorkflow(){if(!state.triage.length)triageInbox();const item=state.triage.find(x=>!x.executed);if(!item)return toast('All triaged workflows have been processed');item.executed=true;if(item.risk==='Sensitive'){item.action='Queued for human approval';toast(`${item.agent} routed this message to human review`)}else{state.tasks.unshift({id:Date.now(),title:item.subject,owner:item.route,status:'Assigned',createdAt:new Date().toISOString()});localStorage.setItem('havenroute.tasks',JSON.stringify(state.tasks));toast(`${item.agent} created and routed an operational task`)}renderAgentActivity()}
function openProductivity(){document.querySelectorAll('.nav-item').forEach(x=>x.classList.remove('active'));$('#productivityBtn').classList.add('active');state.selected=null;hideAlternateViews();$('#readerContent').classList.add('hidden');$('#emptyState').classList.add('hidden');$('#readerPanel').classList.add('productivity-mode');$('#productivityView').classList.remove('hidden');$('#folderTitle').textContent='Productivity'}
function showUndo(){$('#undoBar').classList.remove('hidden');clearTimeout(state.undoTimer);state.undoTimer=setTimeout(()=>$('#undoBar').classList.add('hidden'),7000)}
function snoozeSelected(){const m=selectedMessage();if(!m)return toast('Select a message first');const value=prompt('Snooze until (YYYY-MM-DD HH:MM)',new Date(Date.now()+3600000).toISOString().slice(0,16).replace('T',' '));if(!value)return;const until=Date.parse(value.replace(' ','T'));if(!Number.isFinite(until)||until<=Date.now())return toast('Choose a valid future date and time');m.snoozedUntil=until;state.selected=null;$('#readerContent').classList.add('hidden');$('#emptyState').classList.remove('hidden');renderList();toast(`Message snoozed until ${new Date(until).toLocaleString()}`)}
function labelSelected(){const m=selectedMessage();if(!m)return toast('Select a message first');const labels=['guest','operations','urgent','finance'];m.label=labels[(labels.indexOf(m.label)+1)%labels.length];toast(`Label changed to ${m.label}`);renderList()}

$('#replyAllBtn').onclick=()=>prepareReply('all');$('#forwardBtn').onclick=()=>prepareReply('forward');$('#archiveBtn').onclick=()=>moveSelected('archive');$('#deleteBtn').onclick=()=>moveSelected('trash');
$('#snoozeBtn').onclick=snoozeSelected;$('#labelBtn').onclick=labelSelected;
$('#taskFromMailBtn').onclick=()=>{const m=selectedMessage();if(!m)return;state.tasks.unshift({id:Date.now(),title:m.subject,owner:state.staff.email,status:'Flagged',due:new Date(Date.now()+86400000).toISOString().slice(0,10)});localStorage.setItem('havenroute.tasks',JSON.stringify(state.tasks));toast('Email added to the daily task list')};
$('#recallBtn').onclick=()=>{const m=selectedMessage();if(!m||m.folder!=='sent')return;if(m.readByRecipient)return toast('Recall unavailable because the recipient opened this message');if(Date.now()-(m.sentAt||0)>120000&&!m.scheduled)return toast('Recall window has expired');m.folder='drafts';m.time='Recalled';state.selected=null;$('#readerContent').classList.add('hidden');$('#emptyState').classList.remove('hidden');renderList();toast('Message recalled and returned to Drafts')};
function selectedForBulk(){return state.messages.filter(m=>state.selectedIds.has(m.id))}
function bulkMove(folder){const items=selectedForBulk();if(!items.length)return toast('Select at least one message');items.forEach(m=>{m.folder=folder;m.unread=false});state.selectedIds.clear();$('#selectAllMail').checked=false;renderList();toast(`${items.length} message(s) moved to ${folder}`)}
$('#selectAllMail').onchange=e=>{if(e.target.checked)filtered().forEach(m=>state.selectedIds.add(m.id));else state.selectedIds.clear();renderList()};$('#bulkArchiveBtn').onclick=()=>bulkMove('archive');$('#bulkDeleteBtn').onclick=()=>bulkMove('trash');
$('#sweepSenderBtn').onclick=()=>{const items=selectedForBulk(),sender=items[0]?.email;if(!sender)return toast('Select a message from the sender to sweep');state.messages.filter(m=>m.email===sender&&m.folder==='inbox').forEach(m=>{m.folder='archive';m.unread=false});state.selectedIds.clear();renderList();toast(`All inbox mail from ${sender} archived`)};
$('#quickStepBtn').onclick=()=>{const items=selectedForBulk();if(!items.length)return toast('Select messages before running a Quick Step');items.forEach(m=>{m.folder='archive';m.unread=false;m.label='operations'});state.selectedIds.clear();renderList();toast('Quick Step completed: labeled, marked read, and archived')};
document.querySelectorAll('[data-smart-reply]').forEach(b=>b.onclick=()=>useSmartReply(b.dataset.smartReply));
$('#toggleCc').onclick=()=>$('#ccFieldWrap').classList.toggle('hidden');$('#toggleBcc').onclick=()=>$('#bccFieldWrap').classList.toggle('hidden');
$('#attachmentBtn').onclick=()=>$('#attachmentInput').click();$('#imageBtn').onclick=()=>$('#imageInput').click();$('#attachmentInput').onchange=e=>addAttachments(e.target.files);$('#imageInput').onchange=e=>addAttachments(e.target.files);
$('#attachmentList').onclick=e=>{const b=e.target.closest('[data-remove-attachment]');if(!b)return;state.attachments.splice(Number(b.dataset.removeAttachment),1);renderAttachments()};
$('#encryptionBtn').onclick=()=>{state.encrypted=!state.encrypted;$('#encryptionBtn').setAttribute('aria-pressed',String(state.encrypted));$('#encryptionBtn').textContent=state.encrypted?'🔒':'🔓';toast(state.encrypted?'Protected delivery enabled':'Protected delivery disabled')};
$('#securityCenterBtn').onclick=()=>toast('Security center: protected delivery and role-aware access are active');
$('#notificationBtn').onclick=()=>{$('#notificationPanel').classList.toggle('hidden');renderNotifications()};$('#markReadBtn').onclick=()=>{state.messages.forEach(m=>m.unread=false);renderList();renderNotifications()};$('#notificationList').onclick=e=>{const b=e.target.closest('[data-notification-id]');if(!b)return;$('#notificationPanel').classList.add('hidden');openMessage(Number(b.dataset.notificationId))};
$('#havenAiBtn').onclick=openAiWorkspace;$('#aiTriageBtn').onclick=triageInbox;
$('#productivityBtn').onclick=openProductivity;
$('#aiView').onclick=e=>{const b=e.target.closest('[data-ai-action]');if(!b)return;const item=b.closest('.review-item');const title=item.querySelector('b').textContent;if(b.dataset.aiAction==='edit'){compose();$('#subjectField').value=`Haven AI review: ${title}`;$('#bodyField').value='Review and edit this agent-drafted response before approval.';return}item.classList.add('resolved');item.innerHTML=`<div><b>${esc(title)}</b><small>${b.dataset.aiAction==='approve'?'Approved by staff and logged':'Rejected and returned to Haven AI'}</small></div>`;renderAgentActivity();toast(`${title}: ${b.dataset.aiAction==='approve'?'approved':'rejected'}`)};
loadStaffIdentity();loadMessages().then(renderNotifications);

document.querySelectorAll('#mailTabs [data-category]').forEach(b=>b.onclick=()=>{document.querySelectorAll('#mailTabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active');state.category=b.dataset.category;renderList()});
document.querySelectorAll('[data-label]').forEach(b=>b.onclick=()=>{state.label=state.label===b.dataset.label?'':b.dataset.label;document.querySelectorAll('[data-label]').forEach(x=>x.classList.toggle('active',state.label===x.dataset.label));renderList()});
$('#undoSendBtn').onclick=()=>{if(!state.lastSent)return;state.messages=state.messages.filter(m=>m.id!==state.lastSent.id);$('#undoBar').classList.add('hidden');renderList();compose();$('#toField').value=state.lastSent.to;$('#subjectField').value=state.lastSent.subject;$('#bodyField').value=String(state.lastSent.body).replace(/<br>/g,'\n');state.lastSent=null;toast('Send undone — message restored')};
$('#templateField').onchange=e=>{const templates={checkin:'Welcome to Oak Haven. Check-in begins at 2:00 PM. Please complete digital check-in before arrival.',directions:'Oak Haven Lodging & Suites is located at Plot 7 & 9 Oakwood Park, Shimawa Village Road, Ogun State.',reservation:'Thank you for choosing Oak Haven. Please confirm your dates, room preference, and number of guests.',handover:'Shift handover: Completed items, open guest requests, operational exceptions, and required follow-up.'};if(templates[e.target.value])$('#bodyField').value=templates[e.target.value]};
$('#savePreferencesBtn').onclick=()=>{const prefs={};document.querySelectorAll('[data-pref]').forEach(x=>prefs[x.dataset.pref]=x.checked);localStorage.setItem('havenroute.preferences',JSON.stringify(prefs));toast('HavenRoute preferences saved')};
const toolCopy={storage:['Storage','Mail and attachments use protected HavenRoute storage. Google Drive and Google Photos sharing becomes available after an administrator authorizes the Google Workspace connection.'],filters:['Rules & filters','Create rules that label, archive, flag, forward, or delete matching messages.'],quicksteps:['Quick Steps','Save one-click combinations such as label, mark read, and archive.'],aliases:['Inboxes & aliases','Add an approved @oakhavensuites.com address for sending and receiving.'],templates:['Templates','Save a reusable response for reservations, arrivals, handovers, or guest support.'],vacation:['Vacation responder','Set dates and an automatic response for incoming mail.'],schedule:['Scheduled messages','Review messages queued for later delivery.'],security:['Security review','Spam and phishing scanning, encryption modes, and MFA are active.'],calendar:['Calendar','Create an appointment, meeting, reminder, or RSVP.'],scheduling:['Scheduling Assistant','Compare participant availability and suggest a meeting time.'],contacts:['Contacts & People Hub','Add staff, guest, vendor, or partner contact details and groups.'],accounts:['Connected accounts','Aggregate approved Gmail, Yahoo, iCloud, IMAP, or POP accounts after administrator authorization.'],microsoft:['Microsoft 365','Attach approved OneDrive or SharePoint files and open Word, Excel, PowerPoint, or Teams.'],addins:['Add-ins','Manage approved Zoom, Trello, and CRM extensions.'],signature:['Signatures & stationery','Create a professional Oak Haven signature for outgoing mail.'],tasks:['Tasks','Open Haven AI operational tasks and follow-ups.'],keep:['Notes','Create a private Oak Haven note.'],gemini:['AI connection','Haven AI is active. An administrator can authorize Gemini through the approved Google Workspace connection.'],meet:['HavenConnect Meet','Start or join a secure Oak Haven meeting.'],chat:['HavenConnect Chat','Open staff messaging in HavenConnect.']};
function openTool(kind){if(kind==='meet'||kind==='chat')return openHavenConnect(kind);const [title,subtitle]=toolCopy[kind]||['Workspace tool','Configure this feature.'];$('#toolTitle').textContent=title;$('#toolSubtitle').textContent=subtitle;let body='';if(kind==='filters')body='<div class="tool-row"><label>Condition<select id="filterCondition"><option>Sender contains</option><option>Subject contains</option><option>Has attachment</option><option>Message size exceeds</option></select></label><label>Value<input id="filterMatch" placeholder="invoice, vendor, or 10 MB"></label></div><label>Action<select id="filterAction"><option>Apply Finance label</option><option>Move to folder</option><option>Flag as priority</option><option>Archive</option><option>Forward to operations@oakhavensuites.com</option><option>Delete</option></select></label><button data-tool-save="filter">Save and activate rule</button>';else if(kind==='quicksteps')body='<label>Quick Step name<input id="quickStepName" value="Archive and mark read"></label><label>Actions<select id="quickStepAction"><option>Label + mark read + archive</option><option>Forward + create task</option><option>Flag + move to Focused</option></select></label><button data-tool-save="quickstep">Save Quick Step</button>';else if(kind==='aliases')body='<label>Approved alias<input id="aliasValue" type="email" placeholder="reservations@oakhavensuites.com"></label><button data-tool-save="alias">Add alias</button><div id="aliasList"></div>';else if(kind==='templates')body='<label>Template name<input id="templateName" placeholder="Guest follow-up"></label><label>Message<textarea id="templateBody" placeholder="Write reusable text"></textarea></label><button data-tool-save="template">Save template</button>';else if(kind==='vacation')body='<div class="tool-row"><label>From<input id="vacationStart" type="date"></label><label>To<input id="vacationEnd" type="date"></label></div><label>Automatic reply<textarea id="vacationText">Thank you for your message. I am away and will respond when I return.</textarea></label><button data-tool-save="vacation">Turn on responder</button>';else if(kind==='calendar')body='<label>Event title<input id="calendarTitle" placeholder="Operations meeting"></label><div class="tool-row"><label>Date<input id="calendarDate" type="date"></label><label>Time<input id="calendarTime" type="time"></label></div><label>Attendees<input id="calendarAttendees" placeholder="staff@oakhavensuites.com"></label><button data-tool-save="calendar">Schedule event</button>';else if(kind==='scheduling')body='<label>Participants<input id="schedulePeople" placeholder="reception@, housekeeping@"></label><label>Duration<select id="scheduleDuration"><option>30 minutes</option><option>60 minutes</option></select></label><button data-tool-save="scheduling">Find available times</button>';else if(kind==='contacts')body='<div class="tool-row"><label>Name<input id="contactName"></label><label>Email<input id="contactEmail" type="email"></label></div><label>Group<select id="contactGroup"><option>Staff</option><option>Guest</option><option>Vendor</option><option>Partner</option></select></label><button data-tool-save="contact">Save contact</button>';else if(kind==='tasks')body=(state.tasks.length?state.tasks.map(x=>`<p><b>${esc(x.title)}</b><br>${esc(x.owner)} · ${esc(x.status)}</p>`).join(''):'<p>No operational tasks yet.</p>')+'<button data-tool-save="task">Add task</button>';else if(kind==='keep')body='<label>Private note<textarea id="noteBody" placeholder="Write a note"></textarea></label><button data-tool-save="note">Save note</button>';else if(kind==='signature')body='<label>Signature name<input id="signatureName" value="Oak Haven professional"></label><label>Signature<textarea id="signatureBody">Warm regards,\nOak Haven Lodging & Suites</textarea></label><button data-tool-save="signature">Save signature</button>';else if(kind==='schedule')body=`<p>${state.messages.filter(x=>x.scheduled).length} message(s) are scheduled for later delivery.</p>`;else body=`<p>${esc(subtitle)}</p><button data-tool-save="${esc(kind)}">Confirm</button>`;$('#toolBody').innerHTML=body;$('#toolModal').classList.remove('hidden');if(kind==='aliases')renderAliases()}
function renderAliases(){const el=$('#aliasList');if(!el)return;const aliases=JSON.parse(localStorage.getItem('havenroute.aliases')||'[]');el.innerHTML=aliases.map(x=>`<span class="alias-chip">${esc(x)}</span>`).join('')}
document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>openTool(b.dataset.tool));
$('#closeTool').onclick=()=>$('#toolModal').classList.add('hidden');$('#toolModal').onclick=e=>{if(e.target.id==='toolModal')$('#toolModal').classList.add('hidden')};$('#toolBody').onclick=e=>{const b=e.target.closest('[data-tool-save]');if(!b)return;const kind=b.dataset.toolSave;if(kind==='alias'){const value=$('#aliasValue').value.trim().toLowerCase();if(!value.endsWith('@oakhavensuites.com'))return toast('Use an approved @oakhavensuites.com alias');const aliases=JSON.parse(localStorage.getItem('havenroute.aliases')||'[]');if(!aliases.includes(value))aliases.push(value);localStorage.setItem('havenroute.aliases',JSON.stringify(aliases));renderAliases();toast('Alias added')}else{const payload={kind,updatedAt:new Date().toISOString()};document.querySelectorAll('#toolBody input,#toolBody textarea,#toolBody select').forEach(x=>payload[x.id]=x.value);localStorage.setItem(`havenroute.tool.${kind}`,JSON.stringify(payload));toast(`${$('#toolTitle').textContent} saved`)}};
function openHavenConnect(view){const inConnect=document.referrer.includes('havenconnect-oak-haven');if(inConnect){window.parent.postMessage({type:'havenroute:navigate',view},'*');toast(`Opening HavenConnect ${view}`);return}window.open(`https://havenconnect-oak-haven.mdonbruce.chatgpt.site/?view=${encodeURIComponent(view)}`,'_blank','noopener,noreferrer')}
$('#meetBtn').onclick=()=>openHavenConnect('meet');$('#chatBtn').onclick=()=>openHavenConnect('chat');$('#appsBtn').onclick=openProductivity;
$('#createTaskBtn').onclick=()=>{const m=selectedMessage();if(!m)return toast('Select a message first');const route=classifyMessage(m);state.tasks.unshift({id:Date.now(),title:m.subject,owner:route.route,status:'Assigned',createdAt:new Date().toISOString()});localStorage.setItem('havenroute.tasks',JSON.stringify(state.tasks));renderAgentActivity();toast(`Task assigned to ${route.department}`)};
$('#runWorkflowBtn').onclick=runNextWorkflow;
$('#loadPolicyExampleBtn').onclick=()=>toast('Policy examples are disabled. Open a verified Oak Haven message to run policy enrichment.');
try{state.tasks=JSON.parse(localStorage.getItem('havenroute.tasks')||'[]');state.triage=JSON.parse(localStorage.getItem('havenroute.triage')||'[]')}catch{}renderAgentActivity();
document.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select'))return;if(e.key.toLowerCase()==='c')compose();if(e.key.toLowerCase()==='e')moveSelected('archive');if(e.key.toLowerCase()==='r')prepareReply('reply');if(e.key==='/'){e.preventDefault();$('#searchInput').focus()}});
$('#bodyField').addEventListener('input',e=>{if(!document.querySelector('[data-pref="smartCompose"]')?.checked)return;const v=e.target.value;if(/thank you for$/i.test(v))e.target.placeholder=' your message. We are happy to assist.';else if(/please confirm$/i.test(v))e.target.placeholder=' your preferred dates and room type.'});
$('#scheduleField').onchange=e=>$('#scheduleDateField').classList.toggle('hidden',e.target.value!=='custom');
document.querySelectorAll('[data-format]').forEach(b=>b.onclick=()=>{const area=$('#bodyField'),start=area.selectionStart,end=area.selectionEnd,text=area.value.slice(start,end);const value=b.dataset.format==='bold'?`**${text||'bold text'}**`:b.dataset.format==='italic'?`_${text||'italic text'}_`:b.dataset.format==='list'?`\n• ${text||'list item'}`:`[${text||'link text'}](https://)`;area.setRangeText(value,start,end,'end');area.focus()});
$('#mentionBtn').onclick=()=>{const area=$('#bodyField'),name=prompt('Mention a contact or role','@Front Desk');if(name){area.setRangeText(name.startsWith('@')?name:'@'+name,area.selectionStart,area.selectionEnd,'end');$('#composeHint').textContent=`${name.startsWith('@')?name:'@'+name} will be highlighted for direct attention.`}};
$('#voiceSearchBtn').onclick=()=>{const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition)return toast('Voice search is not supported by this browser');const rec=new Recognition();rec.lang='en-NG';rec.onresult=e=>{$('#searchInput').value=e.results[0][0].transcript;renderList();toast('Voice search completed')};rec.onerror=()=>toast('Voice search could not start');rec.start()};
function updateOnlineState(){const el=$('#offlineState');if(el)el.textContent=navigator.onLine?'Online':'Offline · changes queued'}addEventListener('online',()=>{updateOnlineState();toast('Back online — queued changes are ready to sync')});addEventListener('offline',()=>{updateOnlineState();toast('Offline mode active')});updateOnlineState();

// HavenRoute open/share + installable PWA
let deferredInstallPrompt=null;
const appShareUrl=()=>window.location.href.split('#')[0];
function openShare(){
  $('#shareLink').value=appShareUrl();
  $('#shareModal').classList.remove('hidden');
}
function closeShare(){ $('#shareModal').classList.add('hidden'); }
async function copyShareLink(){
  try{await navigator.clipboard.writeText(appShareUrl());toast('HavenRoute link copied')}catch{ $('#shareLink').select();document.execCommand('copy');toast('HavenRoute link copied') }
}
async function nativeShare(){
  const data={title:'HavenRoute — Oak Haven Email',text:'Open HavenRoute, the Oak Haven Lodging & Suites email application.',url:appShareUrl()};
  if(navigator.share){try{await navigator.share(data)}catch{}} else {await copyShareLink()}
}
function shareInternally(){
  closeShare();compose();
  $('#subjectField').value='HavenRoute access link';
  $('#bodyField').value=`Open HavenRoute here: ${appShareUrl()}\n\nFor Oak Haven staff use only. Please sign in with your authorized account.`;
  routeBadge();
}
$('#shareBtn').onclick=openShare;
$('#closeShare').onclick=closeShare;
$('#copyLinkBtn').onclick=copyShareLink;
$('#nativeShareBtn').onclick=nativeShare;
$('#emailShareBtn').onclick=shareInternally;
$('#shareModal').addEventListener('click',e=>{if(e.target.id==='shareModal')closeShare()});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstallPrompt=e;$('#installBtn').classList.remove('hidden')});
$('#installBtn').onclick=async()=>{if(deferredInstallPrompt){deferredInstallPrompt.prompt();await deferredInstallPrompt.userChoice;deferredInstallPrompt=null;return}toast('Desktop install: open your browser menu and choose Install HavenRoute or Install app')};
if('serviceWorker' in navigator){window.addEventListener('load',()=>navigator.serviceWorker.register('/havenroute/service-worker.js',{scope:'/havenroute/'}).catch(()=>{}))}

