function openTeamSpace(name){
  const team=teamSpaces[name]; if(!team)return;
  state.selected=null;
  document.querySelectorAll('.nav-item').forEach(x=>x.classList.remove('active'));
  document.querySelectorAll('.team-spaces button').forEach(x=>x.classList.toggle('active',x.dataset.team===name));
  $('#readerPanel').classList.add('team-mode');
  $('#teamView').classList.remove('hidden');
  $('#teamTitle').textContent=name;
  $('#teamDescription').textContent=team.description;
  $('#teamMemberCount').textContent=team.roles.length;
  $('#teamChannelCount').textContent=team.channels.length;
  $('#teamRoles').innerHTML=team.roles.map(([role,detail])=>`<button class="role-chip" data-role-action="${esc(role)}"><span class="role-avatar">${initials(role)}</span><span><b>${esc(role)}</b><small>${esc(detail)}</small></span><i>Open</i></button>`).join('');
  $('#teamChannels').innerHTML=team.channels.map(([channel,detail])=>`<button class="channel-item" data-channel-action="${esc(channel)}"><b>${esc(channel)}</b><small>${esc(detail)}</small><i>Open</i></button>`).join('');
  $('#folderTitle').textContent=name;
}

document.querySelectorAll('.team-spaces button').forEach(b=>b.addEventListener('click',()=>openTeamSpace(b.dataset.team)));
$('#teamComposeBtn').onclick=()=>{compose();$('#subjectField').value=`[Team Space] ${$('#teamTitle').textContent}: `;};
$('#teamRoles').onclick=e=>{const b=e.target.closest('[data-role-action]');if(!b)return;const role=b.dataset.roleAction,route=roleRouting.find(x=>x[0]===role)||roleRouting.find(x=>x[0].includes(role));compose();if(route)$('#toField').value=route[1];$('#subjectField').value=`${$('#teamTitle').textContent} · ${role}: `;routeBadge();toast(`${role} communication route opened`)};
$('#teamChannels').onclick=e=>{const b=e.target.closest('[data-channel-action]');if(!b)return;const channel=b.dataset.channelAction;$('#teamDescription').textContent=`Channel #${channel} is open. Messages and tasks created here route to authorized ${$('#teamTitle').textContent} staff.`;$('#subjectField').value='';toast(`#${channel} channel opened`)};
$('#teamRolesBtn').onclick=()=>$('#teamRoles').scrollIntoView({behavior:'smooth',block:'center'});$('#teamChannelsBtn').onclick=()=>$('#teamChannels').scrollIntoView({behavior:'smooth',block:'center'});

