$('#rbacBtn').onclick=openRbac;$('#rbacRole').onchange=renderRbac;$('#closeRbac').onclick=()=>$('#rbacModal').classList.add('hidden');$('#rbacModal').onclick=e=>{if(e.target.id==='rbacModal')$('#rbacModal').classList.add('hidden')};$('#saveRbacBtn').onclick=()=>{localStorage.setItem(`havenroute.rbac.${$('#rbacRole').value}`,JSON.stringify([...document.querySelectorAll('#rbacPermissions input')].map(x=>x.checked)));$('#rbacModal').classList.add('hidden');toast('Role access policy saved and enforced')};

