function renderRoleMatrix(query=''){const q=query.trim().toLowerCase(),items=roleRouting.filter(row=>row.join(' ').toLowerCase().includes(q));$('#roleMatrix').innerHTML=items.length?items.map(([role,alias,scope])=>`<article><b>${esc(role)}</b><a href="mailto:${esc(alias)}">${esc(alias)}</a><p>${esc(scope)}</p><button data-route-role="${esc(role)}" data-route-alias="${esc(alias)}">Route message</button></article>`).join(''):'<p class="activity-empty">No matching role or responsibility.</p>'}
renderRoleMatrix();
$('#roleSearch').oninput=e=>renderRoleMatrix(e.target.value);
$('#roleMatrix').onclick=e=>{const b=e.target.closest('[data-route-role]');if(!b)return;compose();$('#toField').value=b.dataset.routeAlias;$('#subjectField').value=`Action for ${b.dataset.routeRole}: `;routeBadge();toast(`Secure route opened for ${b.dataset.routeRole}`)};
const orchestration={started:false,done:new Set()};
function setStage(name,status,text){const card=document.querySelector(`[data-stage="${name}"]`);if(!card)return;card.classList.toggle('active',status==='Active');card.classList.toggle('complete',status==='Complete');card.querySelector('span').textContent=status;if(text)card.querySelector('p').textContent=text}
function finishOrchestration(){if(orchestration.done.size<3)return;setStage('reply','Complete','Oak Haven operational tasks completed and logged.');toast('Internal workflow completed')}
$('#runOrchestrationBtn').onclick=()=>{orchestration.started=true;orchestration.done.clear();setStage('reception','Complete','Three intents detected and dispatched in parallel.');[['it','High-priority smart-TV diagnostics sent to it@oakhavensuites.com'],['housekeeping','Compressed mobile task sent to the on-duty Room Attendant'],['dining','Dinner setup sent to dining@oakhavensuites.com and kitchen@oakhavensuites.com']].forEach(([stage,text])=>setStage(stage,'Active',text));setStage('reply','Waiting','Waiting for all three departments to confirm completion.');['completeItBtn','completeHousekeepingBtn','completeDiningBtn'].forEach(id=>$('#'+id).disabled=false);toast('Reception Agent dispatched three parallel tasks')};
[['completeItBtn','it'],['completeHousekeepingBtn','housekeeping'],['completeDiningBtn','dining']].forEach(([id,stage])=>$('#'+id).onclick=()=>{if(!orchestration.started)return;orchestration.done.add(stage);setStage(stage,'Complete',stage==='it'?'Remote network fix logged by IT.':stage==='housekeeping'?'Room Attendant confirmed towel delivery.':'Server confirmed the dinner arrangement.');$('#'+id).disabled=true;finishOrchestration()});
$('#previewPagingBtn').onclick=()=>{$('#guardrailResult').innerHTML='<b>Mobile task · Room Attendant</b><br>Deliver two fresh bath towels to the assigned suite now. Confirm completion in HavenRoute.';toast('Compressed staff page generated')};
$('#testOverrideBtn').onclick=()=>{$('#guardrailResult').innerHTML='<b>Automation locked · Management approval required</b><br>Financial payout request routed to gm@oakhavensuites.com and asstmanager@oakhavensuites.com. No external action was taken.';toast('Protected message routed to management')};
try{const prefs=JSON.parse(localStorage.getItem('havenroute.preferences')||'{}');document.querySelectorAll('[data-pref]').forEach(x=>{if(typeof prefs[x.dataset.pref]==='boolean')x.checked=prefs[x.dataset.pref]})}catch{}

// Version 110: operational mail transport, protection, storage, and enterprise controls.
Object.assign(toolCopy,{smtp:['SMTP outbound delivery','Configure authenticated relay, TLS, and retry behavior for outgoing Oak Haven mail.'],imap:['IMAP multi-device sync','Keep mailbox state synchronized across HavenRoute web, desktop, and mobile clients.'],pop3:['POP3 legacy retrieval','Enable only for an approved legacy device that cannot use IMAP.'],mx:['DNS MX records','Check the domain routing records used to deliver mail to @oakhavensuites.com.'],delivery:['Delivery queue','Inspect queued, delivered, retried, and failed messages.'],threats:['Protection check','Scan recent mail for spam, phishing indicators, malware, and unsafe links.'],sharedcalendar:['Shared calendars','Choose which Oak Haven team calendars are visible to this account.'],onedrive:['OneDrive connection','Authorize Microsoft 365 storage for secure attachment links.'],gdrive:['Google Drive connection','Authorize Google Workspace storage for secure attachment links.'],largefiles:['Large-file delivery','Convert large attachments into expiring protected cloud links.'],attachmentscan:['Attachment scans','Review the latest malware and file-safety results.'],aisummary:['Haven AI thread summary','Generate a concise overview, decisions, and next steps from the selected conversation.'],automation:['Mail automation','Configure prioritization, scheduling detection, nudges, and agentic routing.'],users:['User management','Manage mailbox accounts, aliases, roles, and account status.'],compliance:['Compliance center','Review organizational controls and evidence for applicable security programs.'],retention:['Retention policies','Set archiving and deletion periods by message category.'],audit:['Audit logs','Review mailbox sign-ins, sends, deletes, permission changes, and policy actions.'],devices:['Device management','Manage approved desktop and mobile clients and revoke lost devices.'],googleworkspace:['Google Workspace','Connect Drive, Docs, Sheets, Calendar, Meet, and approved add-ons.'],clients:['HavenRoute clients','Review web, installable desktop, mobile, and offline access options.']});
const baseOpenTool=openTool;
openTool=function(kind){
  if(kind==='meet'||kind==='chat')return openHavenConnect(kind);
  const [title,subtitle]=toolCopy[kind]||['Workspace tool','Configure this feature.'];
  const specialized=new Set(['smtp','imap','pop3','mx','delivery','threats','retention','audit','aisummary','sharedcalendar','onedrive','gdrive','largefiles','attachmentscan','automation','users','compliance','devices','googleworkspace','clients']);
  if(!specialized.has(kind))return baseOpenTool(kind);
  $('#toolTitle').textContent=title;$('#toolSubtitle').textContent=subtitle;
  let body='';
  if(kind==='smtp')body='<label>SMTP relay host<input id="smtpHost" placeholder="smtp.provider.example"></label><div class="tool-row"><label>Port<select id="smtpPort"><option>587 · STARTTLS</option><option>465 · TLS</option></select></label><label>Authentication<select id="smtpAuth"><option>OAuth 2.0</option><option>App credential</option></select></label></div><label><input id="smtpTls" type="checkbox" checked> Require TLS for every outbound connection</label><button data-tool-save="smtp">Save SMTP settings</button>';
  else if(kind==='imap')body='<label>IMAP host<input id="imapHost" placeholder="imap.provider.example"></label><div class="tool-row"><label>Port<input id="imapPort" value="993"></label><label>Sync window<select id="imapWindow"><option>All mail</option><option>12 months</option><option>90 days</option></select></label></div><button data-tool-save="imap">Save IMAP sync</button>';
  else if(kind==='pop3')body='<p>POP3 is disabled by default because it can remove messages from the shared server mailbox.</p><label><input id="popEnabled" type="checkbox"> Enable POP3 for one approved legacy client</label><button data-tool-save="pop3">Save POP3 policy</button>';
  else if(kind==='mx')body='<label>Domain<input id="mxDomain" value="oakhavensuites.com" readonly></label><div class="guardrail"><b>MX diagnostic</b><p>Ready to validate the configured mail gateway.</p></div><button data-tool-save="mx">Run MX check</button>';
  else if(kind==='delivery')body=`<p><b>${state.messages.filter(x=>x.scheduled).length}</b> scheduled and <b>0</b> failed messages.</p><button data-tool-save="delivery">Retry pending delivery</button>`;
  else if(kind==='threats')body='<div class="guardrail"><b>Protection layers ready</b><p>Spam scoring, phishing heuristics, attachment scanning, unsafe-link checks, TLS, login alerts, and Zero Trust policy checks are enabled.</p></div><button data-tool-save="threats">Scan recent messages</button>';
  else if(kind==='retention')body='<label>Guest and reservation mail<select id="retentionGuest"><option>7 years</option><option>5 years</option><option>3 years</option></select></label><label>General operations mail<select id="retentionOps"><option>3 years</option><option>1 year</option><option>6 months</option></select></label><button data-tool-save="retention">Save retention policy</button>';
  else if(kind==='audit')body='<p>Audit events record sign-ins, sends, deletes, archive actions, permission changes, and policy updates.</p><button data-tool-save="audit">Export current audit view</button>';
  else if(kind==='aisummary'){const m=selectedMessage();body=m?`<div class="guardrail"><b>${esc(m.subject)}</b><p>${esc(m.preview||'Conversation ready for summarization.')}</p></div><button data-tool-save="aisummary">Generate summary and next steps</button>`:'<p>Select an email conversation first, then open this tool to create its summary and next steps.</p>'}
  else if(kind==='sharedcalendar')body='<label><input id="calendarOps" type="checkbox" checked> Operations calendar</label><label><input id="calendarRooms" type="checkbox" checked> Room and event resources</label><label><input id="calendarManagement" type="checkbox"> Management calendar</label><button data-tool-save="sharedcalendar">Save calendar visibility</button>';
  else body=`<p>${esc(subtitle)}</p><label>Status<select id="${esc(kind)}Status"><option>Request administrator authorization</option><option>Enabled for this account</option><option>Disabled</option></select></label><button data-tool-save="${esc(kind)}">Save setting</button>`;
  $('#toolBody').innerHTML=body;$('#toolModal').classList.remove('hidden');
};

// Gmail-inspired HavenRoute settings center.
const settingsKey='havenroute.mail.settings';
const settingsArrays={labels:['Guest relations','Operations','Urgent','Finance approval'],forwarding:[],blocked:[]};
try{const saved=JSON.parse(localStorage.getItem(settingsKey)||'{}');Object.assign(settingsArrays,saved.arrays||{})}catch{}
function renderSettingsLists(){
  $('#settingsLabelList').innerHTML=settingsArrays.labels.map((x,i)=>`<div><b>${esc(x)}</b><span>Show in label list and message list</span><button type="button" data-remove-label="${i}">Remove</button></div>`).join('')||'<p>No custom labels.</p>';
  $('#forwardingList').innerHTML=settingsArrays.forwarding.map((x,i)=>`<div><b>${esc(x)}</b><span>Verification pending or completed by the mail provider</span><button type="button" data-remove-forward="${i}">Remove</button></div>`).join('')||'<p>No forwarding address configured.</p>';
  $('#blockedAddressList').innerHTML=settingsArrays.blocked.map((x,i)=>`<div><b>${esc(x)}</b><span>Future messages are routed to Spam</span><button type="button" data-remove-blocked="${i}">Unblock</button></div>`).join('')||'<p>No blocked addresses.</p>';
}
function settingsSnapshot(){const values={};new FormData($('#mailSettingsForm')).forEach((v,k)=>values[k]=v);document.querySelectorAll('#mailSettingsForm input[type="checkbox"]').forEach(x=>values[x.name]=x.checked);return{values,arrays:settingsArrays}}
function applySettings(saved){if(!saved?.values)return;Object.entries(saved.values).forEach(([name,value])=>{const inputs=document.querySelectorAll(`[name="${CSS.escape(name)}"]`);inputs.forEach(input=>{if(input.type==='checkbox')input.checked=Boolean(value);else if(input.type==='radio')input.checked=input.value===value;else input.value=value})})}
function openSettings(tab='general'){try{applySettings(JSON.parse(localStorage.getItem(settingsKey)||'{}'))}catch{}renderSettingsLists();$('#settingsModal').classList.remove('hidden');selectSettingsTab(tab)}
function closeSettings(){$('#settingsModal').classList.add('hidden')}
function selectSettingsTab(tab){document.querySelectorAll('[data-settings-tab]').forEach(x=>x.classList.toggle('active',x.dataset.settingsTab===tab));document.querySelectorAll('[data-settings-panel]').forEach(x=>x.classList.toggle('active',x.dataset.settingsPanel===tab))}
$('#settingsBtn').onclick=()=>openSettings();$('#closeSettings').onclick=closeSettings;$('#cancelSettings').onclick=closeSettings;$('#settingsModal').onclick=e=>{if(e.target.id==='settingsModal')closeSettings()};
$('#settingsTabs').onclick=e=>{const b=e.target.closest('[data-settings-tab]');if(b)selectSettingsTab(b.dataset.settingsTab)};
$('#mailSettingsForm').onsubmit=e=>{e.preventDefault();localStorage.setItem(settingsKey,JSON.stringify(settingsSnapshot()));$('#settingsSaveState').textContent=`Saved ${new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}`;toast('HavenRoute settings saved');setTimeout(closeSettings,500)};
$('#createLabelBtn').onclick=()=>{const value=$('#newLabelName').value.trim();if(!value)return toast('Enter a label name');if(!settingsArrays.labels.some(x=>x.toLowerCase()===value.toLowerCase()))settingsArrays.labels.push(value);$('#newLabelName').value='';renderSettingsLists();toast('Label created')};
$('#addForwardingBtn').onclick=()=>{const value=prompt('Forwarding email address');if(!value)return;if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value))return toast('Enter a valid email address');if(!settingsArrays.forwarding.includes(value))settingsArrays.forwarding.push(value);renderSettingsLists();toast('Forwarding address added for provider verification')};
$('#blockAddressBtn').onclick=()=>{const value=prompt('Email address to block');if(!value)return;if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value))return toast('Enter a valid email address');if(!settingsArrays.blocked.includes(value))settingsArrays.blocked.push(value);renderSettingsLists();toast('Address added to blocked senders')};
$('#settingsLabelList').onclick=e=>{const b=e.target.closest('[data-remove-label]');if(!b)return;settingsArrays.labels.splice(Number(b.dataset.removeLabel),1);renderSettingsLists()};
$('#forwardingList').onclick=e=>{const b=e.target.closest('[data-remove-forward]');if(!b)return;settingsArrays.forwarding.splice(Number(b.dataset.removeForward),1);renderSettingsLists()};
$('#blockedAddressList').onclick=e=>{const b=e.target.closest('[data-remove-blocked]');if(!b)return;settingsArrays.blocked.splice(Number(b.dataset.removeBlocked),1);renderSettingsLists()};
$('#testMailConnectionBtn').onclick=()=>{const result=$('#mailConnectionResult');result.textContent='HavenRoute settings valid · provider authorization still required for live SMTP/IMAP';result.classList.add('success');toast('Mail settings validation completed')};
$('#mailSettingsForm').onclick=e=>{const b=e.target.closest('[data-settings-action]');if(!b)return;const action=b.dataset.settingsAction;if(action==='chat'){closeSettings();return openHavenConnect('chat')}if(action==='filter'){closeSettings();return openProductivity(),openTool('filters')}if(action==='alias'){closeSettings();return openProductivity(),openTool('aliases')}const labels={account:'Mail account connection opened',import:'Import workflow opened'};toast(labels[action]||'Settings action opened')};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#settingsModal').classList.contains('hidden'))closeSettings()});

// Version 130: shared Lonex domain-mail administration for HavenRoute and HavenConnect.
let hostedMail={settings:null,mappings:[],canManage:false,credentialConfigured:false};
function ensureHostedMailPanels(){
  const accounts=document.querySelector('[data-settings-panel="accounts"]');
  if(accounts&&!$('#hostedMailboxMappings'))accounts.insertAdjacentHTML('beforeend','<h3>Oak Haven mailbox mapping</h3><p>Every active employee is mapped to an approved @oakhavensuites.com mailbox or alias used by HavenRoute and HavenConnect.</p><div class="settings-list" id="hostedMailboxMappings"><p>Loading staff mailboxes…</p></div>');
  const forwarding=document.querySelector('[data-settings-panel="forwarding"]');
  if(forwarding&&!$('#hostedMailProvider'))forwarding.insertAdjacentHTML('afterbegin','<h3>Secure hosted-domain connection</h3><div class="provider-settings" id="hostedMailProvider"><div><b>Incoming mail</b><span>mail.lonex.com</span><small>IMAP 993 · POP3 995 · SSL required</small></div><div><b>Outgoing mail</b><span>mail.lonex.com</span><small>SMTP 465 · SSL required</small></div></div><div class="setting-row"><div><b>Anti-spam protection</b><small>Apply spam, phishing, malware, and unsafe-link checks.</small></div><label><input name="antiSpam" type="checkbox" checked> Enabled</label></div><h3>Automatic reply</h3><div class="setting-row"><div><b>Auto-reply status</b><small>Send an acknowledgement for new incoming messages.</small></div><label><input name="autoReplyEnabled" type="checkbox"> Enabled</label></div><div class="setting-row"><div><b>Auto-reply subject and message</b></div><div><input name="autoReplySubject" value="Thank you for contacting Oak Haven"><textarea name="autoReplyMessage">Thank you for your message. An Oak Haven team member will respond shortly.</textarea></div></div>');
}
function renderHostedMappings(){const list=$('#hostedMailboxMappings');if(!list)return;list.innerHTML=hostedMail.mappings.map(x=>`<div><b>${esc(x.name)}</b><span>${esc(x.mailbox)} · ${esc(x.role)}</span><em>${esc(x.status)}</em></div>`).join('')||'<p>No active staff accounts were found.</p>'}
function applyHostedMail(){const s=hostedMail.settings||{};settingsArrays.forwarding=[...(s.forwarding||[])];settingsArrays.blocked=[...(s.blocked||[])];const set=(name,value)=>{const input=document.querySelector(`[name="${name}"]`);if(!input)return;if(input.type==='checkbox')input.checked=Boolean(value);else input.value=value??''};set('popStatus',s.popStatus||'disabled');document.querySelectorAll('[name="popStatus"]').forEach(x=>x.checked=x.value===(s.popStatus||'disabled'));document.querySelectorAll('[name="imapStatus"]').forEach(x=>x.checked=x.value===(s.imapEnabled===false?'disabled':'enabled'));set('antiSpam',s.antiSpam!==false);set('autoReplyEnabled',s.autoReply?.enabled);set('autoReplySubject',s.autoReply?.subject);set('autoReplyMessage',s.autoReply?.message);renderSettingsLists();renderHostedMappings()}
async function loadHostedMail(){ensureHostedMailPanels();try{const response=await fetch('/api/admin/mail-settings',{headers:{accept:'application/json'},credentials:'same-origin'}),data=await response.json();if(!response.ok)throw new Error(data.message||'Mail settings could not be loaded.');hostedMail=data;applyHostedMail();const result=$('#mailConnectionResult');if(result)result.textContent=data.credentialConfigured?'Lonex gateway authorization configured':'Lonex server settings saved · gateway authorization required'}catch(error){const saved=JSON.parse(localStorage.getItem('havenroute.hosted-mail')||'null');hostedMail=saved||{settings:{provider:'Lonex',domain:'oakhavensuites.com',incomingHost:'mail.lonex.com',imapPort:993,pop3Port:995,outgoingHost:'mail.lonex.com',smtpPort:465,sslRequired:true,imapEnabled:true,popStatus:'disabled',antiSpam:true,forwarding:[],blocked:[],autoReply:{enabled:false,subject:'Thank you for contacting Oak Haven',message:'Thank you for your message. An Oak Haven team member will respond shortly.'}},mappings:roleRouting.map(([role,mailbox])=>({name:role,mailbox,role,status:'Approved alias'})),canManage:true,credentialConfigured:false};applyHostedMail()}}
const originalOpenMailSettings=openSettings;openSettings=function(tab='general'){originalOpenMailSettings(tab);loadHostedMail()};$('#settingsBtn').onclick=()=>openSettings();
$('#mailSettingsForm').onsubmit=async e=>{e.preventDefault();const values=settingsSnapshot().values,payload={...hostedMail.settings,popStatus:values.popStatus||'disabled',imapEnabled:values.imapStatus!=='disabled',antiSpam:Boolean(values.antiSpam),phishingProtection:Boolean(values.antiSpam),malwareScanning:Boolean(values.antiSpam),forwarding:[...settingsArrays.forwarding],blocked:[...settingsArrays.blocked],autoReply:{enabled:Boolean(values.autoReplyEnabled),subject:values.autoReplySubject||'',message:values.autoReplyMessage||''}};const submit=e.submitter;submit.disabled=true;$('#settingsSaveState').textContent='Saving secure domain settings…';try{const response=await fetch('/api/admin/mail-settings',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify(payload)}),data=await response.json();if(!response.ok)throw new Error(data.message||'Settings could not be saved.');hostedMail=data;localStorage.setItem(settingsKey,JSON.stringify(settingsSnapshot()));localStorage.setItem('havenroute.hosted-mail',JSON.stringify(hostedMail));$('#settingsSaveState').textContent='Saved for HavenRoute and HavenConnect';toast('Secure Oak Haven mail settings saved');setTimeout(closeSettings,600)}catch(error){hostedMail.settings=payload;localStorage.setItem('havenroute.hosted-mail',JSON.stringify(hostedMail));localStorage.setItem(settingsKey,JSON.stringify(settingsSnapshot()));$('#settingsSaveState').textContent='Saved in this HavenConnect workspace';toast('Mail preferences saved; provider authorization is still required');setTimeout(closeSettings,600)}finally{submit.disabled=false}};
$('#testMailConnectionBtn').onclick=async()=>{const result=$('#mailConnectionResult');result.textContent='Checking secure settings…';await loadHostedMail();result.classList.add('success');result.textContent=hostedMail.credentialConfigured?'Lonex secure settings and gateway authorization are configured':'Lonex SSL settings are valid. Add the authorized HTTP mail-gateway credential to activate live mailbox transport.'};
